/// Compute boundary impedance coefficients for a given frequency
pub(super) fn compute_boundary_coefficients(
    simulation: &RoomSimulation,
    boundaries: &ResolvedBoundaries,
    frequency: f64,
) -> anyhow::Result<HashMap<usize, Complex64>> {
    let mut coeffs = HashMap::new();
    let k = simulation.wavenumber(frequency);
    coeffs.insert(
        MARKER_FLOOR as usize,
        boundaries.floor.admittance_term(k, frequency)?,
    );
    coeffs.insert(
        MARKER_CEILING as usize,
        boundaries.ceiling.admittance_term(k, frequency)?,
    );
    coeffs.insert(
        MARKER_FRONT as usize,
        boundaries.front.admittance_term(k, frequency)?,
    );
    coeffs.insert(
        MARKER_BACK as usize,
        boundaries.back.admittance_term(k, frequency)?,
    );
    coeffs.insert(
        MARKER_LEFT as usize,
        boundaries.left.admittance_term(k, frequency)?,
    );
    coeffs.insert(
        MARKER_RIGHT as usize,
        boundaries.right.admittance_term(k, frequency)?,
    );
    Ok(coeffs)
}

pub(super) fn find_containing_element_parallel(mesh: &Mesh, point: Point3D) -> Option<usize> {
    (0..mesh.elements.len())
        .into_par_iter()
        // `find_map_any` can select different adjacent tetrahedra when a
        // source lies on a shared face, making point-load RHS assembly vary
        // between calls (and between CPU/GPU host preparation). Choose the
        // first matching element in mesh order for a stable barycentric basis.
        .find_map_first(|elem_idx| {
            let elem = &mesh.elements[elem_idx];
            if elem.element_type != ElementType::Tetrahedron {
                return None;
            }

            let vertices = elem.vertices();
            if vertices.len() != 4 {
                return None;
            }

            let p0 = &mesh.nodes[vertices[0]];
            let p1 = &mesh.nodes[vertices[1]];
            let p2 = &mesh.nodes[vertices[2]];
            let p3 = &mesh.nodes[vertices[3]];

            if compute_barycentric_coords(point, p0, p1, p2, p3).is_some() {
                Some(elem_idx)
            } else {
                None
            }
        })
}

pub(super) fn compute_barycentric_coords(
    p: Point3D,
    v0: &Point,
    v1: &Point,
    v2: &Point,
    v3: &Point,
) -> Option<[f64; 4]> {
    let v0p = [p.x - v0.x, p.y - v0.y, p.z - v0.z];
    let v01 = [v1.x - v0.x, v1.y - v0.y, v1.z - v0.z];
    let v02 = [v2.x - v0.x, v2.y - v0.y, v2.z - v0.z];
    let v03 = [v3.x - v0.x, v3.y - v0.y, v3.z - v0.z];

    let det = v01[0] * (v02[1] * v03[2] - v02[2] * v03[1])
        - v01[1] * (v02[0] * v03[2] - v02[2] * v03[0])
        + v01[2] * (v02[0] * v03[1] - v02[1] * v03[0]);

    if det.abs() < 1e-15 {
        return None;
    }

    let inv_det = 1.0 / det;

    let c00 = v02[1] * v03[2] - v02[2] * v03[1];
    let c10 = -(v01[1] * v03[2] - v01[2] * v03[1]);
    let c20 = v01[1] * v02[2] - v01[2] * v02[1];

    let c01 = -(v02[0] * v03[2] - v02[2] * v03[0]);
    let c11 = v01[0] * v03[2] - v01[2] * v03[0];
    let c21 = -(v01[0] * v02[2] - v01[2] * v02[0]);

    let c02 = v02[0] * v03[1] - v02[1] * v03[0];
    let c12 = -(v01[0] * v03[1] - v01[1] * v03[0]);
    let c22 = v01[0] * v02[1] - v01[1] * v02[0];

    let lambda1 = (c00 * v0p[0] + c01 * v0p[1] + c02 * v0p[2]) * inv_det;
    let lambda2 = (c10 * v0p[0] + c11 * v0p[1] + c12 * v0p[2]) * inv_det;
    let lambda3 = (c20 * v0p[0] + c21 * v0p[1] + c22 * v0p[2]) * inv_det;
    let lambda0 = 1.0 - lambda1 - lambda2 - lambda3;

    let tol = -1e-10;
    if lambda0 >= tol && lambda1 >= tol && lambda2 >= tol && lambda3 >= tol {
        Some([lambda0, lambda1, lambda2, lambda3])
    } else {
        None
    }
}

#[cfg(test)]
pub(super) fn evaluate_solution_at_point_interpolated(
    mesh: &Mesh,
    solution: &[Complex64],
    point: Point3D,
    containing_element: Option<usize>,
) -> Complex64 {
    if let Some(elem_idx) = containing_element {
        let elem = &mesh.elements[elem_idx];
        let vertices = elem.vertices();

        if vertices.len() == 4 {
            let v0 = &mesh.nodes[vertices[0]];
            let v1 = &mesh.nodes[vertices[1]];
            let v2 = &mesh.nodes[vertices[2]];
            let v3 = &mesh.nodes[vertices[3]];

            if let Some(bary) = compute_barycentric_coords(point, v0, v1, v2, v3) {
                return solution[vertices[0]] * bary[0]
                    + solution[vertices[1]] * bary[1]
                    + solution[vertices[2]] * bary[2]
                    + solution[vertices[3]] * bary[3];
            }
        }
    }

    // Fallback: nearest node
    let mut min_dist = f64::MAX;
    let mut nearest_node = 0;

    for (i, node) in mesh.nodes.iter().enumerate() {
        let dist =
            (node.x - point.x).powi(2) + (node.y - point.y).powi(2) + (node.z - point.z).powi(2);
        if dist < min_dist {
            min_dist = dist;
            nearest_node = i;
        }
    }

    solution[nearest_node]
}

#[cfg(test)]
mod tests {
    use super::compute_barycentric_coords;
    use sonium_fem::mesh::Point;
    use sonium_xem::Point3D;

    fn pt(x: f64, y: f64, z: f64) -> Point {
        Point { x, y, z }
    }

    /// Non-right tet whose cofactor matrix is NOT symmetric: catches the
    /// transposed-coefficient bug that a right-angle tet cannot detect.
    /// Hand-verified: p = 0.25*v1 + 0.25*v2 + 0.1*v3 (+ 0.4*v0).
    #[test]
    fn barycentric_coords_reproduce_point_on_non_symmetric_tet() {
        let v0 = pt(0.0, 0.0, 0.0);
        let v1 = pt(1.0, 0.0, 0.0);
        let v2 = pt(1.0, 1.0, 0.0);
        let v3 = pt(0.0, 0.0, 1.0);
        let p = Point3D::new(0.5, 0.25, 0.1);

        let bary = compute_barycentric_coords(p, &v0, &v1, &v2, &v3)
            .expect("point is strictly inside the tet");

        let expected = [0.4, 0.25, 0.25, 0.1];
        for (got, want) in bary.iter().zip(expected) {
            assert!(
                (got - want).abs() < 1e-12,
                "barycentric mismatch: got {bary:?}, want {expected:?}"
            );
        }

        // Partition of unity + exact reproduction of p for an arbitrary tilted tet.
        let v0 = pt(0.1, 0.2, 0.3);
        let v1 = pt(1.3, 0.0, 0.2);
        let v2 = pt(0.2, 1.1, 0.5);
        let v3 = pt(0.4, 0.3, 1.2);
        let p = Point3D::new(0.45, 0.4, 0.55);
        let bary =
            compute_barycentric_coords(p, &v0, &v1, &v2, &v3).expect("point inside tilted tet");
        let sum: f64 = bary.iter().sum();
        assert!((sum - 1.0).abs() < 1e-12, "weights must sum to 1: {sum}");
        let vs = [&v0, &v1, &v2, &v3];
        for (axis, coord) in [(0, p.x), (1, p.y), (2, p.z)] {
            let repro: f64 = bary
                .iter()
                .zip(vs)
                .map(|(w, v)| w * [v.x, v.y, v.z][axis])
                .sum();
            assert!(
                (repro - coord).abs() < 1e-12,
                "axis {axis}: reproduced {repro}, want {coord}"
            );
        }
    }
}
